// Недельная статистика по Upwork (HTML для Telegram)
const s = $json;
const n = (v) => Number(v || 0);
const topSkills = (str) => {
  const counts = {};
  String(str || '').split(',').map((x) => x.trim()).filter((x) => x && !/^\+\d+ more$/i.test(x)).forEach((x) => { counts[x] = (counts[x] || 0) + 1; });
  return Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([k, c]) => k + ' (' + c + ')').join(', ');
};
const replyRate = n(s.jobs_taken) ? Math.round((n(s.clients) / n(s.jobs_taken)) * 100) : 0;
const tips = [];
if (n(s.jobs_taken) < 5) tips.push('Откликайтесь чаще: 10–15 откликов в неделю — нормальный темп для нового профиля.');
if (n(s.jobs_taken) >= 5 && replyRate < 15) tips.push('Мало ответов на отклики — стоит усилить портфолио и первую строку отклика.');
if (n(s.jobs_skipped) > n(s.jobs_taken) * 3) tips.push('Много пропусков — могу поднять порог оценки, чтобы приходило меньше лишнего.');
if (s.avg_review && n(s.avg_review) < 7) tips.push('Средняя оценка проверки ниже 7 — внимательнее смотрите проекты перед сдачей.');
const lines = [
  '📊 <b>Итоги недели на Upwork</b>',
  '📩 Заказов пришло: <b>' + n(s.jobs_new) + '</b> (подходящих ≥6: ' + n(s.jobs_good) + ')',
  '✅ Взяли (отклик): <b>' + n(s.jobs_taken) + '</b>   ❌ Пропустили: ' + n(s.jobs_skipped),
  '💬 Сообщений от клиентов: <b>' + n(s.msgs) + '</b> (клиентов: ' + n(s.clients) + (n(s.jobs_taken) ? ', ≈' + replyRate + '% от откликов' : '') + ')',
  '🎉 Офферов / контрактов: <b>' + n(s.offers) + '</b>',
  '🛠 Проектов сделано: <b>' + n(s.projects_done) + '</b>, доработок: ' + n(s.revisions) + (s.avg_review ? ', средняя проверка ' + s.avg_review + '/10' : ''),
  topSkills(s.good_skills) ? '🔥 Чаще всего в хороших заказах: ' + topSkills(s.good_skills) : '',
  topSkills(s.taken_skills) ? '🎯 Вы берёте: ' + topSkills(s.taken_skills) : '',
  tips.length ? '💡 <b>Советы:</b>\n• ' + tips.join('\n• ') : '💡 Отличная неделя, так держать!',
];
return { json: { text: lines.filter(Boolean).join('\n\n') } };
